    public Object parsePosition(Map<String, Object> position, Map<String, Object> market)
    {
        //
        // {
        //     "market": "BTC-USD",
        //     "status": "OPEN",
        //     "side": "SHORT",
        //     "size": "-0.407",
        //     "maxSize": "-0.009",
        //     "entryPrice": "118692.04840909090909090909",
        //     "exitPrice": "119526.565625",
        //     "realizedPnl": "476.42665909090909090909088",
        //     "unrealizedPnl": "-57.26681734000000000000037",
        //     "createdAt": "2025-07-14T07:53:55.631Z",
        //     "createdAtHeight": "44140908",
        //     "closedAt": null,
        //     "sumOpen": "0.44",
        //     "sumClose": "0.032",
        //     "netFunding": "503.13121",
        //     "subaccountNumber": 0
        // }
        //
        String marketId = this.safeString(position, "market");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, (String) null, (String) null);
        String symbol = (String) ((Map<String, Object>)marketResolved).get("symbol");
        String side = this.safeStringLower(position, "side");
        String quantity = this.safeString(position, "size");
        if (!java.util.Objects.equals(side, "long"))
        {
            quantity = Precise.stringMul("-1", quantity);
        }
        Long timestamp = this.parse8601(this.safeString(position, "createdAt"));
        return this.safePosition(Helpers.newMap(
            "info", position,
            "id", null,
            "symbol", symbol,
            "entryPrice", this.safeNumber(position, "entryPrice", (Object) null),
            "markPrice", null,
            "notional", null,
            "collateral", null,
            "unrealizedPnl", this.safeNumber(position, "unrealizedPnl", (Object) null),
            "side", side,
            "contracts", this.parseNumber(quantity),
            "contractSize", null,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "hedged", null,
            "maintenanceMargin", null,
            "maintenanceMarginPercentage", null,
            "initialMargin", null,
            "initialMarginPercentage", null,
            "leverage", null,
            "liquidationPrice", null,
            "marginRatio", null,
            "marginMode", null,
            "percentage", null
        ));
    }

